use crate::*;
use crate::owned::tree::{NativeValueSource,NativeTreeKind};
use crate::owned::tree::bulk::*;
use crate::{RetainedWorkOutcome,OriginalReceivingPrimary,retained_clone::RetainedCloneSource};
struct Bank{grant:RetainedCloneGrant,fuel:u64,maximum:u64}
impl Bank{
 fn new(s:&serde_json::Value)->Self{Self{grant:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},fuel:s["fuel"].as_u64().unwrap(),maximum:s["maximumTurns"].as_u64().unwrap()}}
 fn offer(&self)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.grant.maximum_items.min(1),..self.grant}}
 fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.grant));assert!(work<=1);self.grant.maximum_items-=p.copied_items;self.grant.maximum_copy_bytes-=p.copied_bytes;self.grant.maximum_capacity_bytes-=p.retained_capacity_bytes;self.grant.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(work).unwrap();}
 fn receiving(&mut self,turn:RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>)->Result<RetainedCloneStep,OriginalReceivingPrimary>{let p=match &turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};self.post(p,turn.work);turn.result}
 fn retire<T:RetireOwned>(&mut self,value:T){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..self.maximum{if owner.terminal_is_empty(){break}let(step,heap)=crate::observe_retirement_allocations(||owner.step(self.offer()).unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.post(p,owner.last_turn_work());}assert!(owner.terminal_is_empty());}
}
fn law()->serde_json::Value{serde_json::from_str(include_str!("../📐️.json")).unwrap()}
fn run(input:DslValue,cut:Option<u64>,profile:&serde_json::Value,expected_error:Option<&str>){
 let expected=serde_json::Value::from(&input);let mut bank=Bank::new(profile);let mut source=crate::source_fixture::capture(input,&mut bank,Bank::offer,|bank,p,work,_,_|bank.post(p,work));let pointer=std::ptr::from_ref(source.borrow().get());
 let(mut receiver,heap)=crate::observe_retirement_allocations(||<DslValue as NativeReceive<DslValue>>::receiver());assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.grant.maximum_capacity_bytes,&mut callback);let mut null_seen=false;let mut failed=false;
 for n in 0..cut.unwrap_or(bank.maximum){if receiver.output_ready(){break}let d=receiver.demands(source.borrow(),4096).unwrap();let g=bank.offer();for denied in [Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0).then_some(RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().flatten(){let(turn,heap)=crate::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(std::ptr::from_ref(source.borrow().get()),pointer);}
  if d.capacity_bytes>0&&!null_seen{let((turn,attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||receiver.advance(source.borrow(),&mut control,4096,g)));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let error=bank.receiving(turn).err().unwrap();bank.retire(error);null_seen=true;continue}
  let(turn,heap)=crate::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,g));let p=match &turn.result{Ok(step)=>step.progress(),Err(e)=>e.retained_progress()};assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));match bank.receiving(turn){Ok(step)=>if !receiver.output_ready(){assert!(!matches!(step,RetainedCloneStep::Complete(_)))},Err(error)=>{assert_eq!(Some(error.message()),expected_error);bank.retire(error);failed=true;break}}assert!(n<bank.maximum-1);
 }
 if cut.is_none(){assert_eq!(failed,expected_error.is_some());if !failed{assert!(receiver.output_ready());let turn=receiver.take(bank.offer());let p=match &turn.result{Ok(Some((_,p)))=>*p,Ok(None)=>Default::default(),Err(e)=>e.retained_progress()};bank.post(p,turn.work);let(output,_)=turn.result.unwrap().unwrap();assert_eq!(serde_json::Value::from(&output),expected);bank.retire(output);}}
 receiver.begin_close();for _ in 0..bank.maximum{if receiver.terminal_is_empty(){break}let d=receiver.close_demands(4096).unwrap();let g=bank.offer();for denied in [Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0).then_some(RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().flatten(){let(turn,heap)=crate::observe_retirement_allocations(||receiver.close_step(denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.close_demands(4096).unwrap(),d);}let(turn,heap)=crate::observe_retirement_allocations(||receiver.close_step(bank.offer()));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,work);}assert!(receiver.terminal_is_empty());assert_eq!(receiver.close_step(Default::default()).work,0);drop(receiver);for _ in 0..bank.maximum{if source.terminal_is_empty(){break}let(turn,heap)=crate::observe_retirement_allocations(||source.close_step(bank.offer()));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,work);}assert!(source.terminal_is_empty());
}
#[test]fn actual_native_tree_matches_independent_serde_under_one_stock_and_every_cancel_cut(){let row=law();for cut in std::iter::once(None).chain(row["cancelCuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()))){run(DslValue::from(row["input"].clone()),cut,&row["stock"],None);}}
#[test]fn actual_native_tree_original_depth_boundary_retains_rejected_input_until_paid_close(){let row=law();assert_eq!(NATIVE_TREE_MAXIMUM_DEPTH,row["productionMaximumDepth"].as_u64().unwrap()as usize);for depth in row["depthCases"].as_array().unwrap(){let depth=depth.as_u64().unwrap()as usize;let mut original=DslValue::Null;let mut independent=serde_json::Value::Null;for _ in 0..depth{original=DslValue::Array(vec![original]);independent=serde_json::Value::Array(vec![independent]);}assert_eq!(serde_json::Value::from(&original),independent);let rejected=depth>NATIVE_TREE_MAXIMUM_DEPTH;run(original,None,&row[if rejected{"rejectedInputStock"}else{"stock"}],rejected.then(||row["depthFailure"].as_str().unwrap()));}}

#[test]fn native_tree_kind_is_a_pure_allocation_free_shape_header(){let row=law();let values=[DslValue::Null,DslValue::Bool(true),DslValue::Number(crate::Number::UInt(1)),DslValue::String(String::new()),DslValue::Array(Vec::new()),DslValue::Object(Vec::new())];let(kinds,heap)=crate::observe_retirement_allocations(||values.each_ref().map(|v|v.tree_kind().unwrap().as_str()));assert_eq!(heap,(0,0));assert_eq!(serde_json::to_value(kinds).unwrap(),row["expectedKinds"]);let mut bank=Bank::new(&row["stock"]);bank.retire(values);}
